create extension if not exists pgcrypto;
create table if not exists public.wards(name text primary key);
insert into public.wards values('Altos'),('Cidade Leste'),('Dom Pedro II'),('Horto'),('Piçarreira'),('Satélite'),('Taquari'),('Uruguai') on conflict do nothing;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique not null,full_name text,unit_type text not null default 'ala' check(unit_type in('ala','estaca')),ward_name text references public.wards(name),role text not null default 'member',status text not null default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz default now());
create table if not exists public.posts(id uuid primary key default gen_random_uuid(),title text not null,body text not null,kind text default 'Publicação',author_id uuid references public.profiles(id),unit_type text default 'ala',ward_name text references public.wards(name),source_url text,published boolean default true,created_at timestamptz default now());
create table if not exists public.post_comments(id uuid primary key default gen_random_uuid(),post_id uuid references public.posts(id) on delete cascade,author_id uuid references public.profiles(id),body text not null,created_at timestamptz default now());
create table if not exists public.indicator_entries(id uuid primary key default gen_random_uuid(),ward_name text not null references public.wards(name),metric_name text not null,value numeric not null default 0 check(value>=0),month date not null,updated_by uuid references public.profiles(id),updated_at timestamptz default now(),unique(ward_name,metric_name,month));
create table if not exists public.events(id uuid primary key default gen_random_uuid(),title text not null,description text,event_date date not null,event_time text,location text,unit_type text default 'estaca',ward_name text references public.wards(name),created_by uuid references public.profiles(id));
create table if not exists public.personal_events(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,title text not null,date date not null,description text);
create table if not exists public.daily_publications(id uuid primary key default gen_random_uuid(),publish_date date unique not null,title text not null,body text not null,source_url text,enabled boolean default true,published_post_id uuid references public.posts(id));
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,title text not null,body text,link text,read_at timestamptz,created_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and status='approved' and (email='vargas.ywerio@gmail.com' or role in('presidencia','secretaria'))) $$;
create or replace function public.approved() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and status='approved') $$;
create or replace function public.can_ward(w text) returns boolean language sql stable security definer set search_path=public as $$ select is_admin() or exists(select 1 from profiles where id=auth.uid() and status='approved' and (unit_type='estaca' or ward_name=w)) $$;
create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,email,full_name,unit_type,ward_name,status) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.raw_user_meta_data->>'unit_type','ala'),case when coalesce(new.raw_user_meta_data->>'unit_type','ala')='ala' then new.raw_user_meta_data->>'ward_name' else null end,case when lower(new.email)='vargas.ywerio@gmail.com' then 'approved' else 'pending' end);return new;end $$;
drop trigger if exists auth_profile on auth.users;
create trigger auth_profile after insert on auth.users for each row execute procedure public.new_profile();
alter table profiles enable row level security;alter table wards enable row level security;alter table posts enable row level security;alter table post_comments enable row level security;alter table indicator_entries enable row level security;alter table events enable row level security;alter table personal_events enable row level security;alter table daily_publications enable row level security;alter table notifications enable row level security;
create policy "profile own or admin" on profiles for select to authenticated using(id=auth.uid() or is_admin());
create policy "admin manage profiles" on profiles for update to authenticated using(is_admin()) with check(is_admin());
create policy "ward list" on wards for select to authenticated using(approved());
create policy "read posts in scope" on posts for select to authenticated using(approved() and (unit_type='estaca' or can_ward(ward_name)));
create policy "leaders create posts" on posts for insert to authenticated with check(exists(select 1 from profiles p where p.id=auth.uid() and p.status='approved' and (p.email='vargas.ywerio@gmail.com' or p.role in('presidencia','secretaria','bishop','counselor','secretary'))));
create policy "author or admin edit post" on posts for update to authenticated using(author_id=auth.uid() or is_admin()) with check(author_id=auth.uid() or is_admin());
create policy "read comments" on post_comments for select to authenticated using(approved());
create policy "write comments" on post_comments for insert to authenticated with check(approved() and author_id=auth.uid());
create policy "read indicators" on indicator_entries for select to authenticated using(can_ward(ward_name));
create policy "write indicators" on indicator_entries for all to authenticated using(is_admin() or exists(select 1 from profiles p where p.id=auth.uid() and p.status='approved' and p.ward_name=indicator_entries.ward_name and p.role in('bishop','counselor','secretary'))) with check(is_admin() or exists(select 1 from profiles p where p.id=auth.uid() and p.status='approved' and p.ward_name=indicator_entries.ward_name and p.role in('bishop','counselor','secretary')));
create policy "read events" on events for select to authenticated using(approved() and (unit_type='estaca' or can_ward(ward_name)));
create policy "admin events" on events for all to authenticated using(is_admin()) with check(is_admin());
create policy "personal events own" on personal_events for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy "admin daily content" on daily_publications for all to authenticated using(is_admin()) with check(is_admin());
create policy "notifications own" on notifications for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
